import { registerWebComponents } from '@domg-wc/common';
import { VlProgressIndicatorComponent } from '@domg-wc/components/block';

registerWebComponents([VlProgressIndicatorComponent]);

const progressIndicator = document.querySelector('vl-progress-indicator');
// De omschrijving van elke stap, in volgorde.
progressIndicator.steps = ['Stap 1/3: Aanvraag', 'Stap 2/3: Gegevens', 'Stap 3/3: Bevestigen'];
// vl-click-step volgt op een klik op een stap, met de omschrijving en het nummer (vanaf 1) in event.detail. De
// component wijzigt active-step niet zelf.
progressIndicator.addEventListener('vl-click-step', (event) => {
    console.log(event.detail.step, event.detail.number);
});

